if (manager != null)
{
    var lightField = manager.GetType().GetField("_lightSource", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    var light = lightField.GetValue(manager) as UnityEngine.Rendering.Universal.Light2D;
    if (light != null)
        UnityEngine.Debug.Log($"_lightSource references: {light.gameObject.name} (instanceID: {light.gameObject.GetInstanceID()})");
    else
        UnityEngine.Debug.Log("_lightSource is null");
}

// List all objects with SpriteRenderer but no Shadow2DTarget
var renderers = UnityEngine.Object.FindObjectsOfType<UnityEngine.SpriteRenderer>();
int count = 0;
