var manager = UnityEngine.Object.FindObjectOfType<Shadow2DManager>();
if (manager == null) { UnityEngine.Debug.Log("No Shadow2DManager"); return; }

// Get the targets list via reflection
var targetsField = manager.GetType().GetField("_targets", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
var entriesField = manager.GetType().GetField("_entries", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);

var targets = targetsField.GetValue(manager) as System.Collections.IList;
var entries = entriesField.GetValue(manager) as System.Collections.IDictionary;

UnityEngine.Debug.Log($"Targets count: {targets.Count}");
UnityEngine.Debug.Log($"Entries count: {entries.Count}");

// Get light direction
var lightDirMethod = manager.GetType().GetMethod("GetLightDirection", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
var lightDir = (UnityEngine.Vector2)lightDirMethod.Invoke(manager, null);
UnityEngine.Debug.Log($"Light direction: {lightDir}");
UnityEngine.Debug.Log($"Shadow direction (opposite): {-lightDir}");

// Check each shadow entry
foreach (System.Collections.DictionaryEntry entry in entries)
{
    var target = entry.Key;
    var entryValue = entry.Value;
    var anchorField = entryValue.GetType().GetField("Anchor");
    var rendererField = entryValue.GetType().GetField("Renderer");
    var mpbField = entryValue.GetType().GetField("Mpb");

    var anchor = (UnityEngine.Transform)anchorField.GetValue(entryValue);
    var renderer = (UnityEngine.SpriteRenderer)rendererField.GetValue(entryValue);
    var mpb = (UnityEngine.MaterialPropertyBlock)mpbField.GetValue(entryValue);

    UnityEngine.Debug.Log($"Target: {target}, Anchor pos: {anchor.position}, Active: {anchor.gameObject.activeSelf}");
    UnityEngine.Debug.Log($"  Sprite: {(renderer.sprite != null ? renderer.sprite.name : "null")}");
    UnityEngine.Debug.Log($"  Mat: {renderer.sharedMaterial?.name}");

    // Read MPB values
    float opacity = mpb.GetFloat(Shader.PropertyToID("_Opacity"));
    float dirX = mpb.GetFloat(Shader.PropertyToID("_ShadowDirX"));
    float dirY = mpb.GetFloat(Shader.PropertyToID("_ShadowDirY"));
    float stretch = mpb.GetFloat(Shader.PropertyToID("_ShadowStretch"));
    float vMin = mpb.GetFloat(Shader.PropertyToID("_SpriteVMin"));
    float vInvH = mpb.GetFloat(Shader.PropertyToID("_SpriteVInvH"));

    UnityEngine.Debug.Log($"  MPB: opacity={opacity}, dir=({dirX},{dirY}), stretch={stretch}, vMin={vMin}, vInvH={vInvH}");
}

// Check the material
var matField = manager.GetType().GetField("_shadowMaterial", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
var mat = (UnityEngine.Material)matField.GetValue(manager);
if (mat != null)
{
    UnityEngine.Debug.Log($"Shadow Material: {mat.name}, shader: {mat.shader?.name}");
    UnityEngine.Debug.Log($"  _ShadowColor: {mat.GetColor("_ShadowColor")}");
    UnityEngine.Debug.Log($"  renderQueue: {mat.renderQueue}");
}

