// Load ShadowCircle sprite and assign to TestShadow
var sprites = UnityEngine.Resources.LoadAll<UnityEngine.Sprite>("Assets/Flynn/Art/Shadows/ShadowCircle");
if (sprites.Length > 0)
{
    UnityEngine.Debug.Log($"Found {sprites.Length} sprites");
}
else
{
    // Try loading the texture and finding sprites
    var tex = UnityEngine.AssetDatabase.LoadAssetAtPath<UnityEngine.Texture2D>("Assets/Flynn/Art/Shadows/ShadowCircle.png");
    if (tex != null)
    {
        var allSprites = UnityEngine.Resources.FindObjectsOfTypeAll<UnityEngine.Sprite>();
        foreach (var s in allSprites)
        {
            if (s.texture == tex)
            {
                UnityEngine.Debug.Log($"Found sprite: {s.name} from ShadowCircle texture");
            }
        }
    }
}

// Alternative: just set a dark color on the existing sprite from the Crate
var testShadow = UnityEngine.GameObject.Find("TestShadow");
if (testShadow != null)
{
    var sr = testShadow.GetComponent<UnityEngine.SpriteRenderer>();
    // Use the parent's sprite as a shadow
    var parentSr = testShadow.transform.parent.GetComponent<UnityEngine.SpriteRenderer>();
    if (parentSr != null && parentSr.sprite != null)
    {
        sr.sprite = parentSr.sprite;
        sr.color = new UnityEngine.Color(0, 0, 0, 0.5f);
        sr.sortingOrder = -10;
        sr.flipX = parentSr.flipX;

        // Position below the crate
        testShadow.transform.localPosition = new UnityEngine.Vector3(0.5f, -0.5f, 0);
        testShadow.transform.localScale = new UnityEngine.Vector3(1.2f, 0.5f, 1);

        UnityEngine.Debug.Log($"TestShadow configured with sprite: {sr.sprite.name}, color: {sr.color}");
    }
}

